using Schedule_Creator_V2.Models;
using Schedule_Creator_V2.Models.Records;
using System.IO;
using System.Net;

namespace Schedule_Creator_V2.Services.Email
{
    internal class EmailBuilder
    {
        // EMAIL VALUES
        public string emailHTML;
        public List<Staff> sendTo;
        public List<Staff> sendCc;
        public string subject;
        public bool isFlagged;
        public bool isMarkedImportant;
        // HEADER VARIABLES
        public string preHeaderText;
        public string organizationLabel;
        public string headerLabel;
        public string emailHeading;
        public string headerSubtitle;
        public string headerImage;
        // FOOTER VARIABLES
        public string footerOrganization;
        public string footerWebsiteLink;
        public string footerText;
        public string footerImage;

        public EmailBuilder(
            List<Staff> sendTo,
            List<Staff> sendCc,
            string subject,
            string emailHeading,
            string headerSubtitle,
            bool? isFlagged = false,
            bool? isMarkedImportant = false            
        )
        {
            this.sendTo = sendTo;
            this.sendCc = sendCc;
            this.subject = subject;
            this.emailHeading = emailHeading;
            this.headerSubtitle = headerSubtitle;

            // DEFAULT VALUES
            this.emailHTML = File.ReadAllText("Models/Objects/Email.html");
            this.isFlagged = isFlagged ?? false;
            this.isMarkedImportant = isMarkedImportant ?? false;
            this.preHeaderText = "";
            this.organizationLabel = "University Recreation";
            this.headerLabel = "UWGB Climbing Tower";
            this.footerOrganization = "University of Wisconsin Green Bay";
            this.footerWebsiteLink = "https://www.uwgb.edu/urec/adventure/climbing/";
            this.footerText = "You are receiving this message because you are affiliated with the UWGB Climbing Tower.";
            this.headerImage = "data:image/png;base64,";
            this.footerImage = "data:image/png;base64,";
        }
        public List<Staff> SendTo { get; set; }
        public List<Staff> SendCc { get; set; }
        public string Subject { get; set; }
        public bool IsFlagged { get; set; }
        public bool IsMarkedImportant { get; set; }

    public string BuildCustomHeader(string emailHTML, CustomHeaderInputs inputs)
    {
        return emailHTML.Replace("<!-- HEADER -->", $"""
        <tr id="headerSection">
            <td bgcolor="#bfdbd4" class="content-padding email-style-05">
                <div class="email-style-06" id="organizationLabel">
                    {this.organizationLabel}
                </div>

                <div class="email-style-07" id="organizationName">
                    {inputs.OrganizationName}
                </div>
            </td>
        </tr>

        <tr>
            <td bgcolor="#0f5640" class="email-style-08">
                <img alt="UWGB Climbing Tower"
                     class="email-style-09"
                     id="headerImage"
                     src="{headerImage}" />
            </td>
        </tr>

        <tr id="headerTextSection">
            <td class="content-padding">
                <div id="headerLabel">
                    {inputs.HeaderLabel}
                </div>

                <div id="emailHeading">
                    {inputs.EmailHeading}
                </div>

                <div id="headerSubtitle">
                    {inputs.HeaderSubtitle}
                </div>
            </td>
        </tr>
        """);
    }
        public string BuildCustomBody(string emailHTML, CustomBodyInputs inputs)
        {
            return emailHTML.Replace("<!-- BODY -->", $"""
                <tr id="bodySection">
                    <td class="content-padding email-style-14">
                        <div class="email-style-15" id="recipientGreeting">
                            {inputs.RecipientGreeting}
                        </div>

                        <div class="email-style-16" id="emailBody">
                            <p class="email-style-17">
                                {inputs.EmailBody}
                            </p>
                        </div>
                    </td>
                </tr>
                """
            );
        }
    public string BuildCustomAnnouncements(string emailHTML, CustomAnnouncementsInputs inputs)
    {
        string announcementItems = string.Join(
            Environment.NewLine,
            inputs.AnnouncementsList.Select(announcement => $"""
            <li class="announcement-item">
                {WebUtility.HtmlEncode(announcement)}
            </li>
            """)
        );

        return emailHTML.Replace("<!-- ANNOUNCEMENTS -->", $"""
        <tr id="announcementsSection">
            <td bgcolor="#bfdbd4"
                class="content-padding announcements-section">

                <div class="section-label" id="announcementsLabel">
                    {WebUtility.HtmlEncode(inputs.AnnouncementsLabel)}
                </div>

                <div class="announcements-intro" id="announcementsIntro">
                    {WebUtility.HtmlEncode(inputs.AnnouncementsIntro)}
                </div>

                <ul class="announcements-list" id="announcementsList">
                    {announcementItems}
                </ul>

            </td>
        </tr>
        """);
    }
        public string BuildCustomRequest(
        string emailHTML,
        CustomRequestInputs inputs)
        {
            return emailHTML.Replace("<!-- REQUEST -->", $"""
        <tr id="requestSection">
            <td class="content-padding email-style-19">
                <table border="0"
                       cellpadding="0"
                       cellspacing="0"
                       role="presentation"
                       width="100%">

                    <tr>
                        <td bgcolor="#f5f7f6"
                            class="email-style-20">

                            <div class="section-label"
                                 id="requestLabel">
                                {WebUtility.HtmlEncode(inputs.RequestLabel)}
                            </div>

                            <div class="email-style-21"
                                 id="requestTitle">
                                {WebUtility.HtmlEncode(inputs.RequestTitle)}
                            </div>

                            <div class="email-style-22"
                                 id="requestBody">
                                {WebUtility.HtmlEncode(inputs.RequestBody)}
                            </div>

                            <table border="0"
                                   cellpadding="0"
                                   cellspacing="0"
                                   class="email-style-23"
                                   role="presentation">

                                <tr>
                                    <td align="center"
                                        bgcolor="#54b948"
                                        class="email-style-24">

                                        <a class="email-style-25"
                                           href="{WebUtility.HtmlEncode(inputs.RequestLink)}"
                                           id="requestButton">
                                            {WebUtility.HtmlEncode(inputs.RequestButton)}
                                        </a>

                                    </td>
                                </tr>

                            </table>

                        </td>
                    </tr>

                </table>
            </td>
        </tr>
        """);
        }
        public string BuildCustomAttachments(string emailHTML, CustomAttachmentsInputs inputs)
        {
            string listItems = string.Join(
                Environment.NewLine,
                inputs.AttachmentsList.Select(item => $"""
            <li>
                {WebUtility.HtmlEncode(item)}
            </li>
            """)
            );

            return emailHTML.Replace("<!-- ATTACHMENTS -->", $"""
        <tr id="attachmentsSection">
            <td bgcolor="#bfdbd4"
                class="content-padding email-style-26">

                <div class="section-label"
                     id="attachmentsLabel">
                    {WebUtility.HtmlEncode(inputs.AttachmentsLabel)}
                </div>

                <div class="email-style-27"
                     id="attachmentsIntro">
                    {WebUtility.HtmlEncode(inputs.AttachmentsIntro)}
                </div>

                <div class="email-style-28"
                     id="attachmentsList">

                    <ul class="email-style-29">
                        {listItems}
                    </ul>

                </div>

            </td>
        </tr>
        """);
        }
        public string BuildCustomSignature(
    string emailHTML,
    CustomSignatureInputs inputs)
        {
            string senderPhoneHtml = string.IsNullOrWhiteSpace(inputs.SenderPhone)
                ? string.Empty
                : $"""
            <div class="email-style-33" id="senderPhone">
                {WebUtility.HtmlEncode(inputs.SenderPhone)}
            </div>
            """;

            return emailHTML.Replace("<!-- SIGNATURE -->", $"""
        <tr id="signatureSection">
            <td class="content-padding email-style-30">

                <div class="email-style-31" id="signatureClosing">
                    {WebUtility.HtmlEncode(inputs.SignatureClosing)}
                </div>

                <div class="email-style-32" id="senderName">
                    {WebUtility.HtmlEncode(inputs.SenderName)}
                </div>

                <div class="email-style-33" id="senderTitle">
                    {WebUtility.HtmlEncode(inputs.SenderTitle)}
                </div>

                <div class="email-style-33" id="senderOrganization">
                    {WebUtility.HtmlEncode(inputs.SenderOrganization)}
                </div>

                <div class="email-style-34">
                    <a class="email-style-35"
                       href="mailto:{WebUtility.HtmlEncode(inputs.SenderEmail)}"
                       id="senderEmail">
                        {WebUtility.HtmlEncode(inputs.SenderEmail)}
                    </a>
                </div>

                {senderPhoneHtml}

            </td>
        </tr>
        """);
        }
        public string BuildCustomFooter(string emailHTML, CustomFooterInputs inputs)
        {
            return emailHTML.Replace("<!-- FOOTER -->", $"""
                <tr id="footerSection">
                    <td align="center"
                        bgcolor="#0f5640"
                        class="content-padding email-style-36">

                        <img alt="UWGB UREC Outdoors logo"
                                class="email-style-37"
                                id="footerLogo"
                                src="{WebUtility.HtmlEncode(inputs.FooterLogoSource)}"
                                width="145" />

                        <div class="email-style-38"
                                id="footerOrganization">
                            {WebUtility.HtmlEncode(inputs.FooterOrganization)}
                        </div>

                        <div class="email-style-39">
                            <a class="email-style-40"
                                href="{WebUtility.HtmlEncode(inputs.FooterWebsiteUrl)}"
                                id="footerWebsiteLink">
                                {WebUtility.HtmlEncode(inputs.FooterWebsiteLink)}
                            </a>
                        </div>

                        <div class="email-style-41"></div>

                        <div class="email-style-42"
                                id="footerText">
                            {WebUtility.HtmlEncode(inputs.FooterText)}
                        </div>

                    </td>
                </tr>
                """
            );
        }

    }
}
